import { IconTile, Menu, MenuItem, Sidebar, SidebarFooter, SidebarHeader, SidebarItem, SidebarSearch, SidebarSection, SidebarUser } from '@strata/react';
import { IconLayoutGrid, IconSettings, IconSparkles, IconUsers } from '@strata/icons';

export function AppNav({ collapsed, onCollapsedChange, openSearch }) {
  return (
    <Sidebar aria-label="Main" variant="floating" collapsed={collapsed} onCollapsedChange={onCollapsedChange}>
      <SidebarHeader logo={<IconTile tint="none"><IconSparkles /></IconTile>} title="Tempo" subtitle="Plan the team's week" />
      <SidebarSearch shortcut="⌘K" onPress={openSearch} />
      <SidebarSection title="General">
        <SidebarItem href="/" icon={<IconLayoutGrid />}>Overview</SidebarItem>
        <SidebarItem icon={<IconUsers />} label="Employees" count={2}>
          <SidebarItem href="/people/jonah">Jonah Adams</SidebarItem>
          <SidebarItem href="/people/yuri" isCurrent>Yuri Jackson</SidebarItem>
        </SidebarItem>
      </SidebarSection>
      <SidebarFooter>
        <SidebarItem href="/settings" icon={<IconSettings />}>Settings</SidebarItem>
        <SidebarUser name="Maya Chen" description="maya@example.com" menu={<Menu><MenuItem id="out">Sign out</MenuItem></Menu>} />
      </SidebarFooter>
    </Sidebar>
  );
}
